<?php
require 'config.php';require 'includes/functions.php';$pdo=db();$action=$_GET['action']??'list';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$fa=$_POST['form_action']??'';
if($fa==='issue'){$bid=filter_var($_POST['book_id']??null,FILTER_VALIDATE_INT);$mid=filter_var($_POST['member_id']??null,FILTER_VALIDATE_INT);$due=$_POST['due_date']??'';$d=DateTime::createFromFormat('Y-m-d',$due);if(!$bid||!$mid||!$d||$d->format('Y-m-d')!==$due)$errors[]='Choose a book, member, and valid due date.';
if(!$errors){try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT available FROM books WHERE id=? FOR UPDATE');$s->execute([$bid]);$b=$s->fetch();if(!$b||(int)$b['available']<1)throw new RuntimeException('Book not found or no copies available.');$s=$pdo->prepare("INSERT INTO loans(book_id,member_id,issue_date,due_date,status) VALUES(?,?,CURDATE(),?,'issued')");$s->execute([$bid,$mid,$due]);$s=$pdo->prepare('UPDATE books SET available=available-1 WHERE id=?');$s->execute([$bid]);$pdo->commit();flash('success','Book issued.');redirect('loans.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e instanceof RuntimeException?$e->getMessage():'Could not issue book.';}}$action='issue';}
if($fa==='return'){$lid=(int)($_POST['loan_id']??0);try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT book_id,status FROM loans WHERE id=? FOR UPDATE');$s->execute([$lid]);$l=$s->fetch();if(!$l||$l['status']!=='issued')throw new RuntimeException('Loan is not currently issued.');$s=$pdo->prepare("UPDATE loans SET status='returned',return_date=CURDATE() WHERE id=?");$s->execute([$lid]);$s=$pdo->prepare('UPDATE books SET available=available+1 WHERE id=?');$s->execute([$l['book_id']]);$pdo->commit();flash('success','Book returned.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger',$e instanceof RuntimeException?$e->getMessage():'Could not return book.');}redirect('loans.php');}}
$books=$pdo->query('SELECT id,title,available FROM books WHERE available>0 ORDER BY title')->fetchAll();$members=$pdo->query('SELECT id,full_name,student_code FROM members ORDER BY full_name')->fetchAll();$rows=$pdo->query('SELECT l.*,b.title,m.full_name FROM loans l JOIN books b ON b.id=l.book_id JOIN members m ON m.id=l.member_id ORDER BY l.id DESC')->fetchAll();$pageTitle='Issue / Return';require 'includes/header.php'; ?>
<?php if($action==='issue'): ?><div class="heading"><div><h1>Issue a book</h1><p>Availability is updated automatically.</p></div><a class="btn btn-outline-secondary" href="loans.php">Back</a></div><?php if($errors): ?><div class="alert alert-danger"><?php foreach($errors as $er)echo '<div>'.e($er).'</div>'; ?></div><?php endif; ?>
<?php if(!$books||!$members): ?><div class="alert alert-info">Add at least one available book and one member before issuing.</div><?php endif; ?><form method="post" class="panel"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="form_action" value="issue"><div class="row g-3"><div class="col-md-6"><label class="form-label">Book</label><select class="form-select" name="book_id" required><option value="">Choose a book</option><?php foreach($books as $b): ?><option value="<?= (int)$b['id'] ?>"><?= e($b['title']) ?> (<?= (int)$b['available'] ?> available)</option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Member</label><select class="form-select" name="member_id" required><option value="">Choose a member</option><?php foreach($members as $m): ?><option value="<?= (int)$m['id'] ?>"><?= e($m['full_name']) ?> — <?= e($m['student_code']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Due date</label><input class="form-control" type="date" min="<?= date('Y-m-d') ?>" name="due_date" value="<?= date('Y-m-d',strtotime('+14 days')) ?>" required></div></div><button class="btn btn-primary mt-4" <?= (!$books||!$members)?'disabled':'' ?>>Confirm issue</button></form>
<?php else: ?><div class="heading"><div><h1>Issue &amp; return</h1><p>Track active borrowing and completed returns.</p></div><a href="loans.php?action=issue" class="btn btn-primary">+ Issue a book</a></div><div class="panel p-0 overflow-hidden"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Book</th><th>Member</th><th>Issued</th><th>Due</th><th>Status</th><th>Action</th></tr></thead><tbody>
<?php foreach($rows as $r): $late=$r['status']==='issued'&&$r['due_date']<date('Y-m-d'); ?><tr><td><?= e($r['title']) ?></td><td><?= e($r['full_name']) ?></td><td><?= e($r['issue_date']) ?></td><td><?= e($r['due_date']) ?></td><td><?= $r['status']==='returned'?'Returned':($late?'Overdue':'Issued') ?></td><td><?php if($r['status']==='issued'): ?><form method="post" onsubmit="return confirm('Mark as returned?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="form_action" value="return"><input type="hidden" name="loan_id" value="<?= (int)$r['id'] ?>"><button class="btn btn-sm btn-outline-success">Mark returned</button></form><?php else: ?><?= e((string)$r['return_date']) ?><?php endif; ?></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="6" class="text-center py-4 text-secondary">No loans yet.</td></tr><?php endif; ?></tbody></table></div></div><?php endif; ?><?php require 'includes/footer.php'; ?>
